mapper.select:
/** manager-action-log-mapper.getManagerActionLogListByParam (관리자 메뉴 사용 이력 관리 조회) */ SELECT A.action_log_id, DATE_FORMAT(A.created_date, '%Y-%m-%d %H:%i:%s') AS created_date, A.remote_addr AS remote_addr, A.request_uri, A.request_method, A.login_type, A.login_id AS login_id FROM (
SELECT AL.action_log_id, AL.created_date, AL.remote_addr, AL.request_uri, AL.request_method, AL.login_type, AL.login_id FROM op_manager_action_log AL
ORDER BY AL.created_date DESC
) A

/** manager-action-log-mapper.getUserActionLogListByParam (사용자 메뉴 사용 이력 관리 조회) */ SELECT A.action_log_id, DATE_FORMAT(A.created_date, '%Y-%m-%d %H:%i:%s') AS created_date, A.remote_addr AS remote_addr, A.request_uri, A.request_method, A.login_type, A.login_id AS login_id FROM (
SELECT AL.action_log_id, AL.created_date, AL.remote_addr, AL.request_uri, AL.request_method, AL.login_type, AL.login_id FROM op_user_action_log AL
ORDER BY AL.created_date DESC
) A
